INSERT INTO quiz_questions (id, topic_id, difficulty, question, options, correct_option, explanation) VALUES (8, 'arrays_slices', 'junior', 'Почему этот код может удерживать в памяти весь большой массив, даже если нужны лишь первые 2 элемента?
