INSERT INTO quiz_questions (id, topic_id, difficulty, question, options, correct_option, explanation) VALUES (94, 'caching_redis', 'middle', 'Кэш на sync.Map используется для хранения значений Redis. В методе, вызываемом из горутин, есть такой код. Какая проблема возникнет при активной нагрузке?

```go
func (c *Cache) Get(k string) (string, bool) {
