INSERT INTO quiz_questions (id, topic_id, difficulty, question, options, correct_option, explanation) VALUES (103, 'benchmarks_profiling', 'intern', 'Что произойдёт, если в тестовом файле объявить функцию `func BenchmarkFoo(b *testing.B)` в пакете foo_test без импорта testing?', '[{"id": "A", "text": "Всё скомпилируется, testing подключается автоматически"}, {"id": "B", "text": "Ошибка компиляции: undefined: testing"}, {"id": "C", "text": "Функция просто не будет обнаружена как бенчмарк"}, {"id": "D", "text": "Ошибка времени выполнения при запуске бенчмарка"}]'::jsonb, 'B', 'Тип *testing.B требует явного импорта пакета testing; без него компилятор выдаст undefined: testing.') ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_id, difficulty, question, options, correct_option, explanation) VALUES (104, 'benchmarks_profiling', 'intern', 'Какое zero value у переменной типа `[]byte` (nil-слайс)?', '[{"id": "A", "text": "len = 0, cap = 0, значение == nil"}, {"id": "B", "text": "len = 0, cap = 0, значение == []byte{}"}, {"id": "C", "text": "len = 1, cap = 1"}, {"id": "D", "text": "panic при первом обращении"}]'::jsonb, 'A', 'Zero value слайса — nil, у которого len и cap равны 0; nil-слайс безопасен для range и append.') ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_id, difficulty, question, options, correct_option, explanation) VALUES (105, 'benchmarks_profiling', 'intern', 'Что выведет код?
