INSERT INTO quiz_questions (id, topic_id, difficulty, question, options, correct_option, explanation) VALUES (123, 'channels', 'intern', 'Какой синтаксис правильно создаёт буферизованный канал строк ёмкостью 5?', '[{"id": "A", "text": "c := make(chan string, 5)"}, {"id": "B", "text": "c := chan string(5)"}, {"id": "C", "text": "c := new(chan string, 5)"}, {"id": "D", "text": "c := make(chan string)[5]"}]'::jsonb, 'A', 'Встроенная функция make(chan T, cap) создаёт буферизованный канал; new возвращает указатель на канал и не принимает ёмкость.') ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_id, difficulty, question, options, correct_option, explanation) VALUES (124, 'channels', 'intern', 'Каким оператором проверяют, что канал закрыт, при получении значения?', '[{"id": "A", "text": "v := <-c, c == nil"}, {"id": "B", "text": "v, ok := <-c"}, {"id": "C", "text": "v := close(<-c)"}, {"id": "D", "text": "if <-c == closed"}]'::jsonb, 'B', 'Форма v, ok := <-c возвращает ok == false, если канал закрыт и буфер пуст; это идиоматичный способ проверки закрытия.') ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_id, difficulty, question, options, correct_option, explanation) VALUES (125, 'channels', 'intern', 'Какой тип у параметра функции, которая только принимает значения из канала?
