INSERT INTO quiz_questions (id, topic_id, difficulty, question, options, correct_option, explanation) VALUES (130, 'channels', 'junior', 'Какой из select-блоков заблокируется навсегда (кроме случая, когда канал будет готов)?', '[{"id": "A", "text": "select { case <-c: }  (c — nil-канал)"}, {"id": "B", "text": "select { default: }"}, {"id": "C", "text": "select { case c <- 1: }  (небуферизованный c, нет получателя)"}, {"id": "D", "text": "select {}  — пустой select"}]'::jsonb, 'D', 'Пустой select{} блокируется навсегда без вариантов; вариант A тоже блокируется, но это конкретный nil-канал case, тогда как D — каноническая «вечная блокировка».') ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_id, difficulty, question, options, correct_option, explanation) VALUES (131, 'channels', 'junior', 'Что выведет код?
