INSERT INTO quiz_questions (id, topic_id, difficulty, question, options, correct_option, explanation) VALUES (381, 'cryptography', 'intern', 'Какое значение по умолчанию (zero value) имеет переменная типа []byte в Go?', '[{"id": "A", "text": "nil"}, {"id": "B", "text": "пустой слайс длины 0, но не nil"}, {"id": "C", "text": "строка \"\""}, {"id": "D", "text": "слайс из одного нулевого байта"}]'::jsonb, 'A', 'Zero value для слайса — nil (len=0, cap=0). Пустой слайс []byte{} создаётся только явно, и хотя len тоже 0, он не равен nil при сравнении с nil через ==.') ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_id, difficulty, question, options, correct_option, explanation) VALUES (382, 'cryptography', 'intern', 'Что выведет этот код?
