INSERT INTO quiz_questions (id, topic_id, difficulty, question, options, correct_option, explanation) VALUES (383, 'cryptography', 'intern', 'Какой тип возвращает функция sha256.Sum256 из пакета crypto/sha256?', '[{"id": "A", "text": "[]byte"}, {"id": "B", "text": "string"}, {"id": "C", "text": "[32]byte"}, {"id": "D", "text": "hash.Hash"}]'::jsonb, 'C', 'sha256.Sum256 возвращает массив фиксированной длины [32]byte (не слайс) — по значению, что удобно для сравнения, но требует среза [:] при передаче в функции, ожидающие []byte.') ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_id, difficulty, question, options, correct_option, explanation) VALUES (384, 'cryptography', 'intern', 'Что выведет код?
