INSERT INTO quiz_questions (id, topic_id, difficulty, question, options, correct_option, explanation) VALUES (385, 'cryptography', 'intern', 'Какое ключевое слово в Go используется для сравнения типов во время выполнения при работе с криптографическими интерфейсами?', '[{"id": "A", "text": "instanceof"}, {"id": "B", "text": "switch с type (type switch)"}, {"id": "C", "text": "is"}, {"id": "D", "text": "match"}]'::jsonb, 'B', 'В Go нет instanceof/is; для проверки динамического типа интерфейса используется type switch (switch v := x.(type)) или type assertion. Это часто применяют, например, чтобы различить реализацию hash.Hash.') ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_id, difficulty, question, options, correct_option, explanation) VALUES (386, 'cryptography', 'junior', 'Что выведет этот код?
