INSERT INTO quiz_questions (id, topic_id, difficulty, question, options, correct_option, explanation) VALUES (444, 'docker_kubernetes', 'intern', 'Какое ключевое слово в Go используется для объявления переменной с автоматическим выводом типа?', '[{"id": "A", "text": "var"}, {"id": "B", "text": "let"}, {"id": "C", "text": "auto"}, {"id": "D", "text": ":="}]'::jsonb, 'D', 'Короткое объявление := выводит тип из правого выражения; var тоже объявляет переменную, но требует явного типа или инициализатора, а let и auto в Go не существуют.') ON CONFLICT (id) DO NOTHING;
