INSERT INTO quiz_questions (id, topic_id, difficulty, question, options, correct_option, explanation) VALUES (464, 'design_patterns_go', 'intern', 'Какое ключевое слово в Go используется для создания анонимной функции (лямбды)?', '[{"id": "A", "text": "lambda"}, {"id": "B", "text": "closure"}, {"id": "C", "text": "func"}, {"id": "D", "text": "fn"}]'::jsonb, 'C', 'Анонимная функция в Go объявляется через ключевое слово func без имени. Lambda и fn — из других языков.') ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_id, difficulty, question, options, correct_option, explanation) VALUES (465, 'design_patterns_go', 'intern', 'Какой тип имеет выражение? 
