INSERT INTO quiz_questions (id, topic_id, difficulty, question, options, correct_option, explanation) VALUES (663, 'grpc_protobuf', 'intern', 'Какое ключевое слово используется в Go для объявления метода, который будет реализовывать gRPC-интерфейс сервиса на серверной стороне?', '[{"id": "A", "text": "service"}, {"id": "B", "text": "func"}, {"id": "C", "text": "rpc"}, {"id": "D", "text": "method"}]'::jsonb, 'B', 'В Go нет ключевых слов service/rpc/method; сервер реализует сгенерированный интерфейс обычными методами с ключевым словом func. rpc и service — это синтаксис .proto-файла, а не Go.') ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_id, difficulty, question, options, correct_option, explanation) VALUES (664, 'grpc_protobuf', 'intern', 'Что выведет этот код?
