INSERT INTO quiz_questions (id, topic_id, difficulty, question, options, correct_option, explanation) VALUES (724, 'http2_http3', 'intern', 'Какое значение по умолчанию (zero value) имеет поле строкового типа в структуре, описывающей HTTP/3-настройки?', '[{"id": "A", "text": "nil"}, {"id": "B", "text": "0"}, {"id": "C", "text": "пустая строка \"\""}, {"id": "D", "text": "\"http/3\""}]'::jsonb, 'C', 'Zero value для string в Go — пустая строка ""; nil применим только к указателям, слайсам, мапам, каналам и интерфейсам.') ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_id, difficulty, question, options, correct_option, explanation) VALUES (725, 'http2_http3', 'intern', 'Какое ключевое слово используется в Go для объявления типа, реализующего интерфейс http.RoundTripper для HTTP/3-транспорта?', '[{"id": "A", "text": "interface"}, {"id": "B", "text": "struct"}, {"id": "C", "text": "type"}, {"id": "D", "text": "func"}]'::jsonb, 'C', 'Для объявления именованного типа (например, своего транспорта) используется ключевое слово type; интерфейсы и структуры также объявляются через type.') ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_id, difficulty, question, options, correct_option, explanation) VALUES (726, 'http2_http3', 'junior', 'Что выведет этот код про server push и слайсы?
