INSERT INTO quiz_questions (id, topic_id, difficulty, question, options, correct_option, explanation) VALUES (743, 'io_files', 'intern', 'Какой интерфейс должен реализовать тип, чтобы его можно было передать в io.Copy как источник данных?', '[{"id": "A", "text": "io.Writer с методом Write([]byte) (int, error)"}, {"id": "B", "text": "io.Reader с методом Read([]byte) (int, error)"}, {"id": "C", "text": "io.Closer с методом Close() error"}, {"id": "D", "text": "io.Seeker с методом Seek(int64, int) (int64, error)"}]'::jsonb, 'B', 'io.Copy(dst Writer, src Reader) читает из src, поэтому источник должен реализовывать io.Reader. io.Writer нужен для приёмника (dst).') ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_id, difficulty, question, options, correct_option, explanation) VALUES (744, 'io_files', 'intern', 'Что произойдёт при выполнении этого кода?
