INSERT INTO quiz_questions (id, topic_id, difficulty, question, options, correct_option, explanation) VALUES (745, 'io_files', 'intern', 'Какой пакет стандартной библиотеки предоставляет буферизованное чтение и запись (Reader/Writer/Scanner)?', '[{"id": "A", "text": "os"}, {"id": "B", "text": "io"}, {"id": "C", "text": "bufio"}, {"id": "D", "text": "bytes"}]'::jsonb, 'C', 'Именно пакет bufio содержит bufio.NewReader, bufio.NewWriter и bufio.Scanner для эффективной буферизации. io определяет лишь интерфейсы, os — файловые операции.') ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_id, difficulty, question, options, correct_option, explanation) VALUES (746, 'io_files', 'junior', 'Что выведет код?
