INSERT INTO quiz_questions (id, topic_id, difficulty, question, options, correct_option, explanation) VALUES (804, 'leetcode_patterns', 'intern', 'Какой из вариантов корректно объявляет переменную типа map[string]int в Go?', '[{"id": "A", "text": "var m map[string]int = make(map[string]int)"}, {"id": "B", "text": "map m[string]int"}, {"id": "C", "text": "var m = map[string]int()"}, {"id": "D", "text": "m := map[string]int{}()"}]'::jsonb, 'A', 'make создаёт инициализированную мапу нужного типа. Варианты B и D — невалидный синтаксис, а C похоже на приведение типа, но для мапы так писать нельзя.') ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_id, difficulty, question, options, correct_option, explanation) VALUES (805, 'leetcode_patterns', 'intern', 'Какое ключевое слово в Go используется для отправки значения в канал?', '[{"id": "A", "text": "send"}, {"id": "B", "text": "<-"}, {"id": "C", "text": "go"}, {"id": "D", "text": "chan"}]'::jsonb, 'B', 'Оператор <- служит и для отправки (ch <- v), и для приёма (v := <-ch) — направление определяется позицией относительно имени канала. go запускает горутину, chan объявляет тип канала.') ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_id, difficulty, question, options, correct_option, explanation) VALUES (806, 'leetcode_patterns', 'junior', 'Что выведет этот код?
```go
