INSERT INTO quiz_questions (id, topic_id, difficulty, question, options, correct_option, explanation) VALUES (865, 'logging', 'intern', 'Какое ключевое слово используется для создания структурированного атрибута в slog?', '[{"id": "A", "text": "slog.Pair(key, value)"}, {"id": "B", "text": "slog.Attr{Key: k, Value: v}"}, {"id": "C", "text": "slog.KeyValue(k, v)"}, {"id": "D", "text": "slog.Field(k, v)"}]'::jsonb, 'B', 'Для структурированных полей в slog используется тип slog.Attr с полями Key и Value; функции Pair/KeyValue/Field в API нет.') ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_id, difficulty, question, options, correct_option, explanation) VALUES (866, 'logging', 'junior', 'Что выведет код?
