```', '[{"id": "A", "text": "100"}, {"id": "B", "text": "1"}, {"id": "C", "text": "0"}, {"id": "D", "text": "ошибка компиляции"}]'::jsonb, 'B', 'Структура передаётся по значению, поэтому mod изменяет только копию; для изменения оригинала нужен указатель *T.') ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_id, difficulty, question, options, correct_option, explanation) VALUES (891, 'memory_allocator', 'junior', 'Что выведет этот код?
