INSERT INTO quiz_questions (id, topic_id, difficulty, question, options, correct_option, explanation) VALUES (903, 'memory_model', 'intern', 'Какое нулевое значение имеет переменная типа map[string]int?', '[{"id": "A", "text": "пустая, но готовая к записи мапа"}, {"id": "B", "text": "nil, чтение из неё возвращает zero value элемента"}, {"id": "C", "text": "0"}, {"id": "D", "text": "ошибка: мапу нельзя объявить без make"}]'::jsonb, 'B', 'Zero value любой map — nil. Чтение из nil-мапы безопасно и возвращает zero value элемента, но запись в nil-мапу вызовет панику.') ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_id, difficulty, question, options, correct_option, explanation) VALUES (904, 'memory_model', 'intern', 'Каким ключевым словом объявляется переменная в Go?', '[{"id": "A", "text": "let"}, {"id": "B", "text": "dim"}, {"id": "C", "text": "var"}, {"id": "D", "text": "def"}]'::jsonb, 'C', 'В Go переменные объявляются через var (или коротко через := внутри функции). Ключевых слов let, dim, def в Go нет.') ON CONFLICT (id) DO NOTHING;
