INSERT INTO quiz_questions (id, topic_id, difficulty, question, options, correct_option, explanation) VALUES (944, 'microservices', 'intern', 'Какое ключевое слово в Go используется внутри функции для отложенного выполнения выражения при выходе из функции?', '[{"id": "A", "text": "defer"}, {"id": "B", "text": "async"}, {"id": "C", "text": "finally"}, {"id": "D", "text": "await"}]'::jsonb, 'A', 'defer откладывает выполнение вызова до момента возврата из функции. В Go нет async/await/finally — это ключевые слова других языков.') ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_id, difficulty, question, options, correct_option, explanation) VALUES (945, 'microservices', 'intern', 'Что выведет код?
```go
type Status int
