INSERT INTO quiz_questions (id, topic_id, difficulty, question, options, correct_option, explanation) VALUES (1022, 'observability', 'middle', 'В сервисе экспортируется счётчик запросов. Что произойдёт при выполнении этого кода?

```go
var n int64
var wg sync.WaitGroup
for i := 0; i < 10; i++ {
    wg.Add(1)
    go func() {
        defer wg.Done()
        atomic.AddInt64(&n, 1)
    }()
}
wg.Wait()
fmt.Println(n)
```', '[{"id": "A", "text": "Выведет 10, так как atomic.AddInt64 обеспечивает атомарность и синхронизацию"}, {"id": "B", "text": "Возможен вывод значения меньше 10 из-за data race на переменной n"}, {"id": "C", "text": "Возможна паника из-за конкурентного доступа к wg"}, {"id": "D", "text": "Возможен deadlock, так как wg.Add вызывается внутри цикла"}]'::jsonb, 'A', 'atomic.AddInt64 атомарно увеличивает счётчик, а wg.Add должен вызываться до запуска горутины, что здесь соблюдено, поэтому данные не теряются.') ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_id, difficulty, question, options, correct_option, explanation) VALUES (1023, 'observability', 'middle', 'В обработчике health check используется таймаут через context. Что выведет код?

```go
