INSERT INTO quiz_questions (id, topic_id, difficulty, question, options, correct_option, explanation) VALUES (1031, 'os_signals', 'intern', 'Какой тип возвращает функция signal.NotifyContext?', '[{"id": "A", "text": "(context.Context, context.CancelFunc)"}, {"id": "B", "text": "(chan os.Signal, func())"}, {"id": "C", "text": "context.Context"}, {"id": "D", "text": "(context.CancelFunc, error)"}]'::jsonb, 'A', 'signal.NotifyContext возвращает контекст и функцию отмены (stop), которую нужно вызвать для освобождения ресурсов после завершения работы.') ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_id, difficulty, question, options, correct_option, explanation) VALUES (1032, 'os_signals', 'intern', 'Что вернёт len после выполнения фрагмента?
