INSERT INTO quiz_questions (id, topic_id, difficulty, question, options, correct_option, explanation) VALUES (1033, 'os_signals', 'intern', 'Какое ключевое слово используется для создания функции, выполняющейся параллельно (горутины)?', '[{"id": "A", "text": "async"}, {"id": "B", "text": "thread"}, {"id": "C", "text": "go"}, {"id": "D", "text": "concurrent"}]'::jsonb, 'C', 'Ключевое слово go перед вызовом функции запускает её в отдельной горутине; в Go нет async/await.') ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_id, difficulty, question, options, correct_option, explanation) VALUES (1034, 'os_signals', 'junior', 'Что произойдёт при выполнении кода?
```go
