INSERT INTO quiz_questions (id, topic_id, difficulty, question, options, correct_option, explanation) VALUES (1213, 'runtime_internals', 'intern', 'Какое ключевое слово используется для запуска новой горутины, которой управляет планировщик рантайма (включая sysmon)?', '[{"id": "A", "text": "go"}, {"id": "B", "text": "async"}, {"id": "C", "text": "thread"}, {"id": "D", "text": "defer"}]'::jsonb, 'A', 'Ключевое слово go запускает функцию в новой горутине; планировщик рантайма (включая sysmon) затем распределяет её выполнение по потокам ОС.') ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_id, difficulty, question, options, correct_option, explanation) VALUES (1214, 'runtime_internals', 'junior', 'Что выведет этот код про таймеры?
