INSERT INTO quiz_questions (id, topic_id, difficulty, question, options, correct_option, explanation) VALUES (1232, 'scheduler_gmp', 'intern', 'Какое ключевое слово в Go используется для запуска горутины?', '[{"id": "A", "text": "async"}, {"id": "B", "text": "go"}, {"id": "C", "text": "goroutine"}, {"id": "D", "text": "thread"}]'::jsonb, 'B', 'Горутина запускается оператором go f(args). Ключевых слов async или goroutine в Go нет.') ON CONFLICT (id) DO NOTHING;
