INSERT INTO quiz_questions (id, topic_id, difficulty, question, options, correct_option, explanation) VALUES (1253, 'reflection', 'intern', 'Как получить тег поля структуры через reflect?', '[{"id": "A", "text": "field.Tag"}, {"id": "B", "text": "field.Get(\"json\")"}, {"id": "C", "text": "field.Tag.Get(\"json\")"}, {"id": "D", "text": "reflect.Tag(field)"}]'::jsonb, 'C', 'StructField.Tag имеет тип reflect.StructTag (строка), а метод Get(key) парсит тег и возвращает значение по ключу.') ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_id, difficulty, question, options, correct_option, explanation) VALUES (1254, 'reflection', 'intern', 'Что вернёт reflect.TypeOf(42).Name()?', '[{"id": "A", "text": "\"int\""}, {"id": "B", "text": "\"int64\""}, {"id": "C", "text": "пустую строку"}, {"id": "D", "text": "\"interface {}\""}]'::jsonb, 'A', 'Для неименованных базовых типов Name() возвращает имя типа, для int — "int".') ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_id, difficulty, question, options, correct_option, explanation) VALUES (1255, 'reflection', 'junior', 'Что произойдёт при выполнении кода?
