INSERT INTO quiz_questions (id, topic_id, difficulty, question, options, correct_option, explanation) VALUES (1259, 'reflection', 'junior', 'Как правильно изменить поле структуры через reflect по указателю?', '[{"id": "A", "text": "v := reflect.ValueOf(&s).Elem(); v.Field(0).SetInt(5)"}, {"id": "B", "text": "v := reflect.ValueOf(s); v.Field(0).SetInt(5)"}, {"id": "C", "text": "v := reflect.New(reflect.TypeOf(s)); v.SetInt(5)"}, {"id": "D", "text": "v := reflect.ValueOf(&s); v.Field(0).SetInt(5)"}]'::jsonb, 'A', 'ValueOf(&s) даёт указатель, Elem() разыменовывает его в адресуемую структуру, и её поля можно менять через SetInt.') ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_id, difficulty, question, options, correct_option, explanation) VALUES (1260, 'reflection', 'junior', 'Что произойдёт?
