INSERT INTO quiz_questions (id, topic_id, difficulty, question, options, correct_option, explanation) VALUES (1392, 'syscalls_os', 'intern', 'Какое ключевое слово используется в Go для запуска функции в отдельной горутине?', '[{"id": "A", "text": "async"}, {"id": "B", "text": "thread"}, {"id": "C", "text": "go"}, {"id": "D", "text": "spawn"}]'::jsonb, 'C', 'Ключевое слово go запускает функцию как горутину. Аналога async/await в Go нет.') ON CONFLICT (id) DO NOTHING;
