INSERT INTO quiz_questions (id, topic_id, difficulty, question, options, correct_option, explanation) VALUES (1394, 'syscalls_os', 'intern', 'Какой пакет нужно импортировать, чтобы вызвать syscall.Kill?', '[{"id": "A", "text": "\"os/signal\""}, {"id": "B", "text": "\"syscall\""}, {"id": "C", "text": "\"os\""}, {"id": "D", "text": "\"runtime\""}]'::jsonb, 'B', 'syscall.Kill объявлен в пакете syscall; os/signal используется для регистрации обработчиков, а не для прямой отправки сигналов.') ON CONFLICT (id) DO NOTHING;
