INSERT INTO quiz_questions (id, topic_id, difficulty, question, options, correct_option, explanation) VALUES (1403, 'syscalls_os', 'middle', 'Что произойдёт при выполнении данного кода?

```go
func main() {
	for i := 0; i < 3; i++ {
		go func() { fmt.Println(i) }()
	}
	time.Sleep(time.Second)
}
```', '[{"id": "A", "text": "Всегда выведется 0 1 2 в порядке запуска"}, {"id": "B", "text": "Может вывестись 3 3 3, так как горутины захватывают общую переменную i"}, {"id": "C", "text": "Ошибка компиляции: нельзя использовать i внутри горутины"}, {"id": "D", "text": "Программа запаникует из-за гонки при чтении i"}]'::jsonb, 'B', 'В версиях до Go 1.22 переменная цикла была общей для всех итераций, поэтому горутины могли прочитать финальное значение 3; в Go 1.22+ семантика изменилась и каждая итерация получает свою переменную, но в классическом примере с замыканием подвох именно в shared-переменной.') ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_id, difficulty, question, options, correct_option, explanation) VALUES (1404, 'syscalls_os', 'middle', 'Что выведет код?

