INSERT INTO quiz_questions (id, topic_id, difficulty, question, options, correct_option, explanation) VALUES (1462, 'testing_basics', 'junior', 'Какой тест завершится ожидаемо (без deadlock) при получении из небуферизованного канала после закрытия?
