INSERT INTO quiz_questions (id, topic_id, difficulty, question, options, correct_option, explanation) VALUES (1533, 'concurrency_patterns', 'intern', 'Какой оператор используется для неблокирующего чтения из канала в select?', '[{"id": "A", "text": "case v, ok := <-ch:"}, {"id": "B", "text": "case v := <-ch:"}, {"id": "C", "text": "default:"}, {"id": "D", "text": "case <-ch:"}]'::jsonb, 'C', 'Ветка default в select выполняется, если ни один канал не готов, что даёт неблокирующую проверку. Остальные варианты — обычные приёмы из каналов.') ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_id, difficulty, question, options, correct_option, explanation) VALUES (1534, 'concurrency_patterns', 'intern', 'Что делает ключевое слово defer в этом фрагменте?
