INSERT INTO quiz_questions (id, topic_id, difficulty, question, options, correct_option, explanation) VALUES (1574, 'maps_internals', 'intern', 'Какая из перечисленных конструкций является корректным ключевым типом мапы в Go?', '[{"id": "A", "text": "map[[]string]int — срез как ключ"}, {"id": "B", "text": "map[map[string]int]bool — мапа как ключ"}, {"id": "C", "text": "map[func()]int — функция как ключ"}, {"id": "D", "text": "map[[2]int]string — массив фиксированной длины как ключ"}]'::jsonb, 'D', 'Ключом мапы может быть только сравнимый тип. Массивы фиксированной длины сравнимы, а срезы, мапы и функции — нет, поэтому варианты A, B, C вызовут ошибку компиляции.') ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_id, difficulty, question, options, correct_option, explanation) VALUES (1575, 'maps_internals', 'junior', 'Что произойдёт при выполнении этого кода?
