}
fmt.Println(m["a"])
```', '[{"id": "A", "text": "10 — v является ссылкой на значение в мапе"}, {"id": "B", "text": "1 — v это копия значения, изменение не влияет на мапу"}, {"id": "C", "text": "0 — нулевое значение после изменения"}, {"id": "D", "text": "Ошибка компиляции: нельзя изменять v"}]'::jsonb, 'B', 'В range по мапе переменная v — это копия значения. Присваивание v не меняет содержимое мапы, поэтому m["a"] остаётся равным 1.') ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_id, difficulty, question, options, correct_option, explanation) VALUES (1582, 'maps_internals', 'junior', 'Что произойдёт с этим кодом?
