INSERT INTO quiz_questions (id, topic_id, difficulty, question, options, correct_option, explanation) VALUES (1619, 'visibility_export', 'junior', 'Что выведет программа?
```go
package main

import "fmt"

type MyErr struct{ Msg string }

func (e *MyErr) Error() string { return e.Msg }

func get() error {
	var e *MyErr = nil
	return e
}

func main() {
	err := get()
	fmt.Println(err == nil)
}
```', '[{"id": "A", "text": "true"}, {"id": "B", "text": "false"}, {"id": "C", "text": "паника nil pointer dereference"}, {"id": "D", "text": "ошибка компиляции"}]'::jsonb, 'B', 'Классическая ловушка: error — интерфейс, содержащий (*MyErr, nil); такой интерфейс не равен nil, потому что type-часть непустая.') ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_id, difficulty, question, options, correct_option, explanation) VALUES (1620, 'visibility_export', 'junior', 'Что выведет код с указателем на элемент среза?
