INSERT INTO quiz_questions (id, topic_id, difficulty, question, options, correct_option, explanation) VALUES (1624, 'visibility_export', 'middle', 'Есть директория `internal/auth` внутри модуля. Какой импорт разрешён правилами Go?', '[{"id": "A", "text": "Любой пакет на любом модуле может импортировать internal/auth по полному пути"}, {"id": "B", "text": "Только пакеты внутри поддерева, чей путь начинается с родителя директории internal (например, example.com/app/...), могут его импортировать"}, {"id": "C", "text": "Только пакет main в корне модуля может импортировать internal/auth"}, {"id": "D", "text": "Никакой пакет не может импортировать internal-пакеты, они доступны только внутри самой директории"}]'::jsonb, 'B', 'Правило internal разрешает импорт только коду, расположенному внутри дерева, корнем которого является родительская директория `internal`. Пакеты вне modules `example.com/app` получат ошибку компиляции.') ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_id, difficulty, question, options, correct_option, explanation) VALUES (1625, 'visibility_export', 'middle', 'Что произойдёт при запуске?

