INSERT INTO quiz_questions (id, topic_id, difficulty, question, options, correct_option, explanation) VALUES (1630, 'wasm', 'intern', 'Какое ключевое слово нужно использовать в Go-файле, чтобы функция стала видимой для JavaScript через js.FuncOf?', '[{"id": "A", "text": "Никакое — достаточно передать функцию в js.FuncOf и вызвать js.Func.Release по завершении"}, {"id": "B", "text": "export"}, {"id": "C", "text": "wasm"}, {"id": "D", "text": "//go:wasmexport для каждой колбэк-функции"}]'::jsonb, 'A', 'Для экспорта Go-функций в JS используют js.FuncOf, который возвращает js.Func; ключевых слов export/wasm в Go нет (//go:wasmexport — про host-функции в других рантаймах, не про браузер).') ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_id, difficulty, question, options, correct_option, explanation) VALUES (1631, 'wasm', 'intern', 'Какой тип имеет результат вызова js.Global().Get("document") в Go-коде для wasm?', '[{"id": "A", "text": "js.Value"}, {"id": "B", "text": "*js.Object"}, {"id": "C", "text": "interface{}"}, {"id": "D", "text": "string"}]'::jsonb, 'A', 'Все обращения к JS-объектам в syscall/js возвращают тип js.Value — обёртку над ссылкой на JS-значение.') ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_id, difficulty, question, options, correct_option, explanation) VALUES (1632, 'wasm', 'junior', 'Что выведет код?
