INSERT INTO quiz_questions (id, topic_id, difficulty, question, options, correct_option, explanation) VALUES (1658, 'websockets', 'junior', 'Что ведёт к утечке горутин в типовом WebSocket-хабе?
```go
select {
case msg := <-c.send:
    c.conn.WriteMessage(websocket.TextMessage, msg)
case <-c.done:
    return
}
```', '[{"id": "A", "text": "if err != nil при WriteMessage без выхода из цикла — клиент не отписывается, горутина висит"}, {"id": "B", "text": "Использование select само по себе создаёт утечку"}, {"id": "C", "text": "WriteMessage обязательно нужно вызывать в отдельной goroutine"}, {"id": "D", "text": "Канал c.done нельзя закрывать в select"}]'::jsonb, 'A', 'Если не обрабатывать ошибки записи и не сигнализировать hub/закрывать done, writer-горутина остаётся висеть на канале.') ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_id, difficulty, question, options, correct_option, explanation) VALUES (1659, 'websockets', 'junior', 'Что выведет код?
```go
